import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices: happy path with single overdue invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date is 2024-10-15, checking as of 2024-10-20
  const result = overdueInvoices([issuedResult.value], '2024-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2024-10-15');
  assert.equal(result[0].daysOverdue, 5);
  assert.equal(result[0].due, 109202);
});

test('overdueInvoices: invoice not yet due', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date is 2024-10-15, checking as of 2024-10-14
  const result = overdueInvoices([issuedResult.value], '2024-10-14');

  assert.equal(result.length, 0);
});

test('overdueInvoices: invoice due today (not overdue)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date is 2024-10-15, checking as of 2024-10-15
  const result = overdueInvoices([issuedResult.value], '2024-10-15');

  assert.equal(result.length, 0);
});

test('overdueInvoices: overdue by 1 day', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date is 2024-10-15, checking as of 2024-10-16
  const result = overdueInvoices([issuedResult.value], '2024-10-16');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices: excludes draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  // Without issuing, it's still draft
  const result = overdueInvoices([invoiceResult.value], '2024-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices: includes issued invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = overdueInvoices([issuedResult.value], '2024-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices: includes partially paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 50000, date: '2024-10-16' });
  const result = overdueInvoices([paidResult.value], '2024-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].due, 59202); // 109202 - 50000
});

test('overdueInvoices: excludes fully paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 109202, date: '2024-10-16' });
  const result = overdueInvoices([paidResult.value], '2024-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices: excludes invoices without dueDate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Manually remove dueDate
  const invoiceWithoutDueDate = { ...issuedResult.value };
  delete invoiceWithoutDueDate.dueDate;

  const result = overdueInvoices([invoiceWithoutDueDate], '2024-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices: multiple invoices sorted by most overdue first', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-05',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-10',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  // Due dates: inv1=2024-10-15, inv2=2024-10-19, inv3=2024-10-24
  // As of 2024-10-25: inv1 is 10 days overdue, inv2 is 6 days, inv3 is 1 day
  const result = overdueInvoices([inv3, inv1, inv2], '2024-10-25');

  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].daysOverdue, 1);
  assert.equal(result[0].number, inv1.number);
  assert.equal(result[1].number, inv2.number);
  assert.equal(result[2].number, inv3.number);
});

test('overdueInvoices: empty list', () => {
  const result = overdueInvoices([], '2024-10-20');

  assert.equal(result.length, 0);
  assert.deepEqual(result, []);
});

test('overdueInvoices: no overdue invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = overdueInvoices([issuedResult.value], '2024-10-10');

  assert.equal(result.length, 0);
});

test('overdueInvoices: different customers', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const result = overdueInvoices([inv1, inv2], '2024-10-20');

  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices: long overdue invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due: 2024-01-15, as of: 2024-10-20 = 279 days overdue
  const result = overdueInvoices([issuedResult.value], '2024-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 279);
});

test('overdueInvoices: EOM terms', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due: 2024-10-31, as of: 2024-11-05 = 5 days overdue
  const result = overdueInvoices([issuedResult.value], '2024-11-05');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 5);
  assert.equal(result[0].dueDate, '2024-10-31');
});

test('overdueInvoices: mix of overdue and not due', () => {
  const invoiceResult1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const invoiceResult2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const issued1 = issueInvoice(invoiceResult1.value, []);
  const issued2 = issueInvoice(invoiceResult2.value, []);

  // As of 2024-10-25: inv1 (due 2024-10-15) is overdue, inv2 (due 2024-11-03) is not
  const result = overdueInvoices([issued1.value, issued2.value], '2024-10-25');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued1.value.number);
});

test('overdueInvoices: same dueDate, sorted by most overdue', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 20 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  // Both have same dueDate (2024-10-15), same daysOverdue
  const result = overdueInvoices([inv1, inv2], '2024-10-20');

  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 5);
  assert.equal(result[1].daysOverdue, 5);
